probes.firstCheck:
// A probe: the first check of a site's default Main.agda on a fresh
// profile, alternating between sites, N rounds.  Prints, per run, the time
// "Agda ready" appeared since navigation, the check's duration as the
// inspector reports it, and the heading.
//
//   CHROME=... node first-check.mjs ROUNDS SITE...

const repo = process.env.REPO;
const cdp = await import(`${repo}/scripts/browser-check/cdp.mjs`);
const { serve } = await import(`${repo}/scripts/browser-check/serve.mjs`);

const RECORDER = `(() => {
  const events = (window.__probe = []);
  let last;
  new MutationObserver(() => {
    const bar = [...document.querySelectorAll(".statusbar > span")].map((e) => e.textContent.replace(/\\s+/g, " ").trim()).join(" | ");
    if (bar !== last) { last = bar; events.push({ t: Math.round(performance.now()), bar }); }
  }).observe(document, { subtree: true, childList: true, characterData: true });
})();`;

const [rounds, ...sites] = process.argv.slice(2);
const rows = [];
for (let round = 0; round < Number(rounds); round++) {
  for (const site of sites) {
    const server = await serve({ root: site });
    const chrome = await cdp.launch(process.env.CHROME);
    const page = chrome.page;
    await page.setViewport(1440, 900);
    await page.addInitScript(RECORDER);
    await page.navigate(`${server.origin}/`);
    let status = "";
    const started = Date.now();
    for (;;) {
      const s = await page.eval(() => ({
        status: document.querySelector(".inspector-status")?.textContent?.trim() ?? "",
        busy: document.querySelector(".spin") !== null,
      }));
      status = s.status;
      if (/ · \d/.test(s.status) && !s.busy) break;
      if (Date.now() - started > 180_000) throw new Error(`timed out: ${s.status}`);
      await new Promise((done) => setTimeout(done, 50));
    }
    const events = await page.eval(() => window.__probe);
    const ready = events.find((e) => /Agda ready/.test(e.bar))?.t;
    const ms = status.match(/([\d.]+) (ms|s)$/);
    const check = ms ? Math.round(Number(ms[1]) * (ms[2] === "s" ? 1000 : 1)) : NaN;
    rows.push({ round, site, ready, check, status });
    console.log(`${round} ${site.split("/").pop()} ready ${ready} ms, check ${check} ms: ${status}`);
    await chrome.close();
    await server.close();
  }
}
console.log(JSON.stringify(rows));

probes.importCheck:
// A probe: the page's check of a Main.agda stored before the page loads
// (in the playground's localStorage key), on a fresh profile, then again
// after a reload in the same profile, which restores what the drive
// persisted.  Prints each check's heading (with the duration the page
// reports), its problems, the compiler log's last lines (after an Infer,
// which shows it), and the requests the page made.
//
//   CHROME=... REPO=... node import-check.mjs SITE MAIN_FILE [OUT_JSON]

import { readFileSync, writeFileSync } from "node:fs";

const repo = process.env.REPO;
const cdp = await import(`${repo}/scripts/browser-check/cdp.mjs`);
const { serve } = await import(`${repo}/scripts/browser-check/serve.mjs`);

const [site, mainFile, outJson] = process.argv.slice(2);
const KEY = "agda-web-ide-beta:doc:/play/Main.agda";
const text = readFileSync(mainFile, "utf8");

const state = () => ({
  status: document.querySelector(".inspector-status")?.textContent?.trim() ?? "",
  bar: [...document.querySelectorAll(".statusbar > span")].map((e) => e.textContent.replace(/\s+/g, " ").trim()).join(" | "),
  busy: document.querySelector(".spin") !== null,
  problems: [...document.querySelectorAll(".problem-card pre")].map((pre) => pre.textContent),
  banner: document.querySelector(".fatal-banner")?.textContent?.trim() ?? null,
  heap: null,
});

async function settle(page, label, timeoutMs) {
  const started = Date.now();
  let last;
  for (;;) {
    last = await page.eval(state);
    if (last.banner) throw new Error(`${label}: the page says ${last.banner}`);
    if (/ · \d/.test(last.status) && !last.busy) return { ...last, wallMs: Date.now() - started };
    if (Date.now() - started > timeoutMs) throw new Error(`${label}: timed out at ${last.status}`);
    await new Promise((done) => setTimeout(done, 250));
  }
}

const server = await serve({ root: site });
const chrome = await cdp.launch(process.env.CHROME);
const page = chrome.page;
await page.setViewport(1440, 900);
// Only on the first navigation: the reload must find what the page stored.
await page.addInitScript(`(() => {
  if (!sessionStorage.getItem("probe-seeded")) {
    sessionStorage.setItem("probe-seeded", "1");
    localStorage.setItem(${JSON.stringify(KEY)}, ${JSON.stringify(text)});
  }
})();`);
const results = { site, date: new Date().toISOString(), browser: chrome.product, runs: [] };
for (const label of ["cold", "reload"]) {
  const before = server.log.length;
  // Give the cold run's persist, which the page does not await, time to
  // commit before the reload.
  if (label === "reload") await new Promise((done) => setTimeout(done, 15_000));
  await page.navigate(`${server.origin}/`);
  const checked = await settle(page, label, 20 * 60_000);
  const requests = server.log.slice(before);
  const run = {
    label,
    status: checked.status,
    bar: checked.bar,
    problems: checked.problems,
    wallMs: checked.wallMs,
    requests: requests.length,
    bytes: requests.reduce((sum, r) => sum + r.bytes, 0),
  };
  results.runs.push(run);
  console.log(JSON.stringify(run));
}
if (outJson) writeFileSync(outJson, JSON.stringify(results, null, 1) + "\n");
await chrome.close();
await server.close();
